                const gpe_entry = try self.dots.getOrPut(tail);
                if (gpe_entry.found_existing) {
                    for (cp_mut_slice(&gpe_entry.value_ptr.*)) |*part| {
                        _ = &part;
                        if (arePartsEqual((part.*).parts, parts)) {
                            (part.*).data = (part.*).data.merge(value);
                            return;
                        }
                    }
                    initial_values = gpe_entry.value_ptr.*;
                }
                var list = try std.array_list.Managed(DotDefine).initCapacity(allocator, (initial_values.len + 1));
                _ = &list;
                if ((initial_values.len > 0)) {
                    _ = list.appendSliceAssumeCapacity(initial_values);
                }
                _ = list.appendAssumeCapacity(DotDefine{ .data = value, .parts = parts });
                gpe_entry.value_ptr.* = try list.toOwnedSlice();
            } else {
                _ = try self.identifiers.put(key, value);
            }
    }

pub fn insertGlobal(self: *Define, allocator: std.mem.Allocator, global: []const []const u8, value_define: *const DefineData) !void {
            const key = global[@as(usize, @intCast((global.len - 1)))];
            const gpe = try self.dots.getOrPut(key);
            if (gpe.found_existing) {
                var list = try std.array_list.Managed(DotDefine).initCapacity(allocator, (gpe.value_ptr.*.len + 1));
                _ = &list;
                _ = list.appendSliceAssumeCapacity(gpe.value_ptr.*);
                _ = list.appendAssumeCapacity(DotDefine{ .parts = global[0..global.len], .data = value_define.* });
                _ = self.allocator.free(gpe.value_ptr.*);
                gpe.value_ptr.* = try list.toOwnedSlice();
            } else {
                var list = try std.array_list.Managed(DotDefine).initCapacity(allocator, 1);
                _ = &list;
                _ = list.appendAssumeCapacity(DotDefine{ .parts = global[0..global.len], .data = value_define.* });
                gpe.value_ptr.* = try list.toOwnedSlice();
            }
    }

pub fn init(allocator: std.mem.Allocator, _user_defines: ?UserDefines, string_defines: ?UserDefinesArray, drop_debugger: bool, omit_unused_global_calls: bool) bun.OOM!*Define {
            const define = try allocator.create(Define);
            errdefer {
            _ = allocator.destroy(define);
            }
            define.* = .{ .allocator = allocator, .identifiers = bun.StringHashMap(IdentifierDefine).init(allocator), .dots = bun.StringHashMap(&.{}, DotDefine).init(allocator), .drop_debugger = drop_debugger };
            _ = try define.dots.ensureTotalCapacity(124);
            const value_define = (&DefineData{ .value = .{ .e_undefined = .{} }, .flags = .{ .valueless = true, .can_be_removed_if_unused = true } });
            for (cp_iter_slice(global_no_side_effect_property_accesses)) |global| {
                _ = &global;
                _ = try define.insertGlobal(allocator, global, value_define);
            }
            const to_string_safe = (&DefineData{ .value = .{ .e_undefined = .{} }, .flags = .{ .valueless = true, .can_be_removed_if_unused = true, .call_can_be_unwrapped_if_unused = .if_unused_and_toString_safe } });
            if (omit_unused_global_calls) {
                for (cp_iter_slice(global_no_side_effect_function_calls_safe_for_to_string)) |global| {
                    _ = &global;
                    _ = try define.insertGlobal(allocator, global, to_string_safe);
                }
            } else {
                for (cp_iter_slice(global_no_side_effect_function_calls_safe_for_to_string)) |global| {
                    _ = &global;
                    _ = try define.insertGlobal(allocator, global, value_define);
                }
            }
            if (_user_defines) |*user_defines| {
                _ = &user_defines;
                var iter = (user_defines.*).iterator();
                _ = &iter;
                _ = try define.insertFromIterator(allocator, @TypeOf((&iter)), (&iter));
            }
            if (string_defines) |*string_defines_| {
                _ = &string_defines_;
                var iter = (string_defines_.*).iterator();
                _ = &iter;
                _ = try define.insertFromIterator(allocator, @TypeOf((&iter)), (&iter));
            }
            return define;
    }

pub fn deinit(self: *Define) void {
            var diter = self.dots.valueIterator();
            _ = &diter;
            while (diter.next()) |key| {
                _ = self.allocator.free(key.*);
            }
            _ = self.dots.clearAndFree();
            _ = self.identifiers.clearAndFree();
            _ = self.allocator.destroy(self);
    }
    pub const Data = DefineData;
};

const string = []const u8;
const defines_path = fs.Path.initWithNamespace("defines.json", "internal");
pub const RawDefines = bun.StringArrayHashMap(string);
pub const UserDefines = bun.StringHashMap(DefineData);
pub const UserDefinesArray = bun.StringArrayHashMap(DefineData);
pub const IdentifierDefine = DefineData;
var empty_dot_defines: [0]DotDefine = &.{};
const nan_val = js_ast.E.Number{ .value = std.math.nan(f64) };
const global_no_side_effect_function_calls_safe_for_to_string = table.global_no_side_effect_function_calls_safe_for_to_string;
const global_no_side_effect_property_accesses = table.global_no_side_effect_property_accesses;
const js_lexer = bun.js_lexer;
const json_parser = bun.json;
const logger = bun.logger;
const strings = bun.strings;
const js_ast = bun.ast;
const Ref = bun.ast.Ref;

pub fn arePartsEqual(a: []const []const u8, b: []const []const u8) bool {
        if ((a.len != b.len)) {
            return false;
        }
        var i: usize = 0;
        _ = &i;
        while ((i < a.len)) : (i = (i + 1)) {
            if ((!strings.eql(a[@as(usize, @intCast(i))], b[@as(usize, @intCast(i))]))) {
                return false;
            }
        }
        return true;
}
